            "points": 2
          },
          {
            "id": "proficient",
            "label": "Proficient",
            "points": 3
          },
          {
            "id": "advanced",
            "label": "Advanced",
            "points": 4
          }
        ],
        "title": "Reasoning"
      },
      {
        "description": "Presents the strongest opposing claim fairly and rebuts it with evidence.",
        "id": "counterclaim",
        "levels": [
          {
            "id": "beginning",
